import { Router, type Request, type Response } from "express";
import {
  createBoard,
  getBoard,
  listBoards,
  deleteBoard,
  createCard,
  getCardsByBoard,
  updateCardPosition,
  deleteCard
} from "../db/boards-table";

export const router = Router();

// GET /api/boards - List all boards
router.get("/api/boards", (req: Request, res: Response): void => {
  try {
    const boards = listBoards();
    res.status(200).json(boards);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// POST /api/boards - Create a new board
router.post("/api/boards", (req: Request, res: Response): void => {
  try {
    const { id, name } = req.body;
    if (!id || !name || typeof id !== "string" || typeof name !== "string") {
      res.status(400).json({ error: "Missing or invalid id or name" });
      return;
    }
    createBoard(id, name);
    const board = getBoard(id);
    res.status(201).json(board);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// GET /api/boards/:id - Get a single board
router.get("/api/boards/:id", (req: Request, res: Response): void => {
  try {
    const { id } = req.params;
    const board = getBoard(id);
    if (!board) {
      res.status(404).json({ error: "Board not found" });
      return;
    }
    res.status(200).json(board);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// DELETE /api/boards/:id - Delete a board
router.delete("/api/boards/:id", (req: Request, res: Response): void => {
  try {
    const { id } = req.params;
    const board = getBoard(id);
    if (!board) {
      res.status(404).json({ error: "Board not found" });
      return;
    }
    deleteBoard(id);
    res.status(200).json({ message: "Board deleted successfully" });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// GET /api/boards/:id/cards - Get all cards for a board
router.get("/api/boards/:id/cards", (req: Request, res: Response): void => {
  try {
    const { id } = req.params;
    const board = getBoard(id);
    if (!board) {
      res.status(404).json({ error: "Board not found" });
      return;
    }
    const cards = getCardsByBoard(id);
    res.status(200).json(cards);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// POST /api/boards/:id/cards - Create a card in a board
router.post("/api/boards/:id/cards", (req: Request, res: Response): void => {
  try {
    const { id: boardId } = req.params;
    const board = getBoard(boardId);
    if (!board) {
      res.status(404).json({ error: "Board not found" });
      return;
    }

    const { id, title, description, columnName, position } = req.body;
    if (
      !id ||
      !title ||
      typeof id !== "string" ||
      typeof title !== "string" ||
      typeof description !== "string" ||
      typeof columnName !== "string" ||
      typeof position !== "number"
    ) {
      res.status(400).json({ error: "Invalid or missing card fields" });
      return;
    }

    createCard(id, boardId, title, description, columnName, position);
    const cards = getCardsByBoard(boardId);
    const createdCard = cards.find((c) => c.id === id);
    res.status(201).json(createdCard);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// PATCH /api/cards/:cardId - Update card position and column
router.patch("/api/cards/:cardId", (req: Request, res: Response): void => {
  try {
    const { cardId } = req.params;
    const { columnName, position } = req.body;

    if (typeof columnName !== "string" || typeof position !== "number") {
      res.status(400).json({ error: "columnName and position are required and must be valid types" });
      return;
    }

    updateCardPosition(cardId, columnName, position);
    res.status(200).json({ message: "Card position updated successfully" });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// DELETE /api/cards/:cardId - Delete a card
router.delete("/api/cards/:cardId", (req: Request, res: Response): void => {
  try {
    const { cardId } = req.params;
    deleteCard(cardId);
    res.status(200).json({ message: "Card deleted successfully" });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

import { Router, type Request, type Response } from "express";

export const router = Router();

interface ForecastDay {
  date: string;
  day: string;
  tempMin: number;
  tempMax: number;
  condition: string;
  humidity: number;
}

interface ForecastResponse {
  location: string;
  latitude: number;
  longitude: number;
  forecast: ForecastDay[];
}

function generateMockForecast(locationName: string, lat: number, lon: number): ForecastResponse {
  const days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const today = new Date();

  const forecast: ForecastDay[] = Array.from({ length: 5 }, (_, i: number) => {
    const date = new Date(today);
    date.setDate(today.getDate() + i);
    const dayName = days[date.getDay()];

    const baseTemp = 15 + Math.sin(lat + lon + i) * 10;
    const tempMin = Math.round(baseTemp - 5);
    const tempMax = Math.round(baseTemp + 5);

    const conditions = ["Sunny", "Partly Cloudy", "Cloudy", "Rainy", "Windy"];
    const conditionIndex = Math.abs(Math.round(lat * 10 + lon * 5 + i)) % conditions.length;
    const condition = conditions[conditionIndex];

    return {
      date: date.toISOString().split("T")[0],
      day: dayName,
      tempMin,
      tempMax,
      condition,
      humidity: Math.abs(Math.round(Math.sin(lat - lon + i) * 30 + 60))
    };
  });

  return {
    location: locationName,
    latitude: lat,
    longitude: lon,
    forecast
  };
}

router.get("/forecast", (req: Request, res: Response): void => {
  const { lat, lon, location } = req.query;

  let latitude = 40.7128;
  let longitude = -74.0060;
  let locationName = "New York, NY";

  if (location) {
    locationName = String(location);
    let hash = 0;
    for (let i = 0; i < locationName.length; i++) {
      hash = locationName.charCodeAt(i) + ((hash << 5) - hash);
    }
    latitude = 30 + (Math.abs(hash % 100) / 100) * 20;
    longitude = -120 + (Math.abs((hash >> 5) % 100) / 100) * 50;
  } else if (lat && lon) {
    latitude = Number(lat);
    longitude = Number(lon);
    if (isNaN(latitude) || isNaN(longitude)) {
      res.status(400).json({ error: "Invalid latitude or longitude parameters" });
      return;
    }
    locationName = `Coordinates (${latitude.toFixed(4)}, ${longitude.toFixed(4)})`;
  }

  const data = generateMockForecast(locationName, latitude, longitude);
  res.json(data);
});

import { Router, type Request, type Response } from "express";
import {
  getAllProducts,
  getProductById,
  insertProduct,
  updateProductStock,
  type Product
} from "../db/products-table";
import { middleware as adminOnlyWriteGuard } from "../middleware/admin-only-write-guard";

export const router = Router();

// Read endpoints (public)
router.get("/products", (req: Request, res: Response): void => {
  try {
    const products = getAllProducts();
    res.status(200).json(products);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch products" });
  }
});

router.get("/products/:id", (req: Request, res: Response): void => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).json({ error: "Invalid product ID" });
    return;
  }

  try {
    const product = getProductById(id);
    if (!product) {
      res.status(404).json({ error: "Product not found" });
      return;
    }
    res.status(200).json(product);
  } catch (error) {
    res.status(500).json({ error: "Failed to fetch product" });
  }
});

// Write endpoints (restricted to admins)
router.post("/products", adminOnlyWriteGuard, (req: Request, res: Response): void => {
  const { name, price, stockCount } = req.body;

  if (typeof name !== "string" || typeof price !== "number" || typeof stockCount !== "number") {
    res.status(400).json({ error: "Missing or invalid product fields (name, price, stockCount)" });
    return;
  }

  try {
    insertProduct(name, price, stockCount);
    res.status(201).json({ message: "Product created successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to create product" });
  }
});

router.put("/products/:id/stock", adminOnlyWriteGuard, (req: Request, res: Response): void => {
  const id = Number(req.params.id);
  const { stockCount } = req.body;

  if (isNaN(id)) {
    res.status(400).json({ error: "Invalid product ID" });
    return;
  }

  if (typeof stockCount !== "number") {
    res.status(400).json({ error: "Invalid or missing stockCount" });
    return;
  }

  try {
    const product = getProductById(id);
    if (!product) {
      res.status(404).json({ error: "Product not found" });
      return;
    }

    updateProductStock(id, stockCount);
    res.status(200).json({ message: "Product stock updated successfully" });
  } catch (error) {
    res.status(500).json({ error: "Failed to update product stock" });
  }
});

import { Router, type Request, type Response } from "express";
import { getProductById, updateProductStock } from "../db/products-table";
import { insertOrder, getAllOrders, getOrderById } from "../db/orders-table";

export const router = Router();

interface CartItem {
  productId: number;
  quantity: number;
}

// POST /orders - Create an order from a cart
router.post("/", (req: Request, res: Response): void => {
  const { customerId, items, paymentStatus } = req.body;

  if (typeof customerId !== "number") {
    res.status(400).json({ error: "Invalid or missing customerId" });
    return;
  }

  if (!Array.isArray(items) || items.length === 0) {
    res.status(400).json({ error: "Cart items must be a non-empty array" });
    return;
  }

  const status = typeof paymentStatus === "string" ? paymentStatus : "pending";

  // Validate stock and products first
  const validatedItems: Array<{ id: number; name: string; price: number; quantity: number }> = [];

  for (const item of items as CartItem[]) {
    if (!item || typeof item.productId !== "number" || typeof item.quantity !== "number" || item.quantity <= 0) {
      res.status(400).json({ error: "Invalid cart item structure" });
      return;
    }

    const product = getProductById(item.productId);
    if (!product) {
      res.status(404).json({ error: `Product with ID ${item.productId} not found` });
      return;
    }

    if (product.stockCount < item.quantity) {
      res.status(400).json({ error: `Insufficient stock for product: ${product.name}` });
      return;
    }

    validatedItems.push({
      id: product.id,
      name: product.name,
      price: product.price,
      quantity: item.quantity
    });
  }

  // Deduct stock
  for (const item of items as CartItem[]) {
    const product = getProductById(item.productId)!;
    updateProductStock(product.id, product.stockCount - item.quantity);
  }

  // Save order
  const lineItemsString = JSON.stringify(validatedItems);
  insertOrder(customerId, lineItemsString, status);

  res.status(201).json({ message: "Order created successfully" });
});

// GET /orders - Retrieve all orders
router.get("/", (req: Request, res: Response): void => {
  const orders = getAllOrders();
  res.json(orders);
});

// GET /orders/:id - Retrieve a single order by ID
router.get("/:id", (req: Request, res: Response): void => {
  const orderId = Number(req.params.id);
  if (isNaN(orderId)) {
    res.status(400).json({ error: "Invalid order ID" });
    return;
  }

  const order = getOrderById(orderId);
  if (!order) {
    res.status(404).json({ error: "Order not found" });
    return;
  }

  res.json(order);
});

import { Router, type Request, type Response } from "express";
import { getOrderById, insertOrder } from "../db/orders-table";

export const router = Router();

/**
 * POST /api/payments/charge
 * Simulates charging a card via an external payment processor.
 * Body parameters:
 *   - orderId: number (optional, if paying for an existing order)
 *   - customerId: number
 *   - lineItems: string
 *   - cardNumber: string
 *   - amount: number
 */
router.post("/charge", (req: Request, res: Response): void => {
  const { orderId, customerId, lineItems, cardNumber, amount } = req.body;

  if (!customerId || !lineItems || !cardNumber || typeof amount !== "number") {
    res.status(400).json({ error: "Missing required payment details (customerId, lineItems, cardNumber, amount)" });
    return;
  }

  // Simple validation simulation
  if (cardNumber.replace(/\s/g, "").length < 12) {
    res.status(400).json({ error: "Invalid card number format" });
    return;
  }

  // Simulate external payment processor logic
  // Cards ending in '0000' are simulated as declined/failed
  const isSuccess = !cardNumber.endsWith("0000");
  const paymentStatus = isSuccess ? "PAID" : "FAILED";

  if (orderId) {
    const existingOrder = getOrderById(Number(orderId));
    if (!existingOrder) {
      res.status(404).json({ error: "Order not found" });
      return;
    }
    // In a real app we would update the order status. 
    // Since orders-table only has insertOrder, getOrderById, and getAllOrders, 
    // we will simulate the response reflecting the payment status for this order.
    res.status(200).json({
      success: isSuccess,
      message: isSuccess ? "Payment processed successfully" : "Payment declined by processor",
      orderId: existingOrder.orderId,
      paymentStatus
    });
    return;
  } else {
    // Create a new order with the payment status
    try {
      insertOrder(Number(customerId), String(lineItems), paymentStatus);
      res.status(201).json({
        success: isSuccess,
        message: isSuccess ? "Payment processed and order created" : "Payment declined, order recorded as FAILED",
        paymentStatus
      });
      return;
    } catch (err: any) {
      res.status(500).json({ error: "Failed to record order: " + err.message });
      return;
    }
  }
});

import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const method = req.method;
  const path = req.path || req.originalUrl || "";

  // Only guard write operations (POST, PUT, PATCH, DELETE) on product routes
  const isProductRoute = path.includes("/products");
  const isWriteMethod = ["POST", "PUT", "PATCH", "DELETE"].includes(method);

  if (!isProductRoute || !isWriteMethod) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing token" });
    return;
  }

  const token = authHeader.substring(7).trim();
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  const [headerB64, payloadB64, signatureB64] = parts;
  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    // Reject every token when JWT_SECRET is unset
    res.status(500).json({ error: "Internal Server Error: JWT secret not configured" });
    return;
  }

  try {
    const dataToSign = `${headerB64}.${payloadB64}`;
    const hmac = createHmac("sha256", jwtSecret);
    hmac.update(dataToSign);
    const expectedSignatureBuffer = hmac.digest();

    // Base64url decode the signature
    const signatureBuffer = Buffer.from(signatureB64, "base64url");

    if (expectedSignatureBuffer.length !== signatureBuffer.length) {
      res.status(401).json({ error: "Unauthorized: Invalid signature" });
      return;
    }

    if (!timingSafeEqual(expectedSignatureBuffer, signatureBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid signature" });
      return;
    }

    // Decode payload
    const payloadJson = Buffer.from(payloadB64, "base64url").toString("utf8");
    const payload = JSON.parse(payloadJson);

    const isAdmin = payload && (payload.role === "admin" || payload.isAdmin === true);
    if (!isAdmin) {
      res.status(403).json({ error: "Forbidden: Admin access required" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Token verification failed" });
  }
}

import { Router, type Request, type Response } from "express";
import { insertTransaction } from "../db/transactions-table";
import { getBankCredentialsByUserId } from "../db/bank-credentials-table";

export const router = Router();

// Mock external bank provider sync logic
function mockFetchExternalTransactions(token: string): Array<{
  amount: number;
  merchant: string;
  date: string;
  category: string;
}> {
  // In a real application, this would use the decrypted token to call a Plaid/Yodlee API.
  // For this service, we simulate fetching 2 mock transactions based on the token length.
  const seed = token.length;
  return [
    {
      amount: -12.50 - (seed % 5),
      merchant: "Mock Merchant " + (seed % 3),
      date: new Date().toISOString().split("T")[0],
      category: "Food & Dining"
    },
    {
      amount: -45.00 - (seed % 10),
      merchant: "Mock Gas Station " + (seed % 2),
      date: new Date().toISOString().split("T")[0],
      category: "Auto & Transport"
    }
  ];
}

// POST /api/bank-sync/sync/:userId
// Triggers a manual sync for a user's linked bank credentials
router.post("/sync/:userId", (req: Request, res: Response): void => {
  const userIdStr = req.params.userId;
  if (!userIdStr) {
    res.status(400).json({ error: "Missing userId parameter" });
    return;
  }

  const userId = Number(userIdStr);
  if (isNaN(userId)) {
    res.status(400).json({ error: "Invalid userId parameter" });
    return;
  }

  try {
    const credentials = getBankCredentialsByUserId(userId);
    if (credentials.length === 0) {
      res.status(404).json({ error: "No bank credentials found for this user" });
      return;
    }

    let syncedCount = 0;
    for (const cred of credentials) {
      // In a real app, we would decrypt cred.encryptedToken first.
      // Here we simulate fetching transactions using the token.
      const externalTxns = mockFetchExternalTransactions(cred.encryptedToken);
      for (const tx of externalTxns) {
        insertTransaction(tx.amount, tx.merchant, tx.date, tx.category);
        syncedCount++;
      }
    }

    res.status(200).json({
      message: "Sync completed successfully",
      syncedTransactionsCount: syncedCount
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "An error occurred during sync" });
  }
});

import { Router, type Request, type Response } from "express";
import { getTransactionById, db } from "../db/transactions-table";

export const router = Router();

// Helper to update a transaction's category in the SQLite database
function updateTransactionCategory(id: number, category: string): boolean {
  try {
    const stmt = db.prepare("UPDATE transactions SET category = ? WHERE id = ?");
    const result = stmt.run(category, id);
    return result.changes > 0;
  } catch (error) {
    return false;
  }
}

// PUT /api/transactions/:id/category
// Updates the category tag of a specific transaction
router.put("/transactions/:id/category", (req: Request, res: Response): void => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).json({ error: "Invalid transaction ID" });
    return;
  }

  const { category } = req.body;
  if (typeof category !== "string") {
    res.status(400).json({ error: "Category must be a string" });
    return;
  }

  const transaction = getTransactionById(id);
  if (!transaction) {
    res.status(404).json({ error: "Transaction not found" });
    return;
  }

  const success = updateTransactionCategory(id, category);
  if (!success) {
    res.status(500).json({ error: "Failed to update category" });
    return;
  }

  const updatedTransaction = getTransactionById(id);
  res.status(200).json(updatedTransaction);
});

import type { Request, Response, NextFunction } from "express";
import { createCipheriv, randomBytes, createHash } from "node:crypto";

const SENSITIVE_KEYS = ["bankToken", "publicToken", "plaidToken", "bankCredentials"];

function encrypt(text: string): string {
  const algorithm = "aes-256-cbc";
  const keySource = process.env.ENCRYPTION_KEY || "default-super-secret-key-32-bytes-long!!!";
  const key = createHash("sha256").update(keySource).digest();
  const iv = randomBytes(16);
  const cipher = createCipheriv(algorithm, key, iv);
  let encrypted = cipher.update(text, "utf8", "hex");
  encrypted += cipher.final("hex");
  return iv.toString("hex") + ":" + encrypted;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  if (req.method !== "POST" && req.method !== "PUT" && req.method !== "PATCH") {
    next();
    return;
  }

  if (req.body && typeof req.body === "object") {
    for (const key of SENSITIVE_KEYS) {
      if (Object.prototype.hasOwnProperty.call(req.body, key)) {
        const val = req.body[key];
        if (typeof val === "string" && val.length > 0) {
          req.body[key] = encrypt(val);
        }
      }
    }
  }

  next();
}

