import { Router, type Request, type Response } from "express";
import { getReadingsBySensor, type Reading } from "../db/readings-table";
import { getDeviceById, type Device } from "../db/devices-table";

export const router = Router();

export interface Alert {
  sensorId: number;
  type: "MISSED_HEARTBEAT" | "OUT_OF_RANGE";
  message: string;
  timestamp: number;
}

// GET /api/alerts/check/:sensorId
// Checks if a sensor has missed its heartbeat (e.g., no readings in the last 5 minutes) 
// or has out-of-range readings (e.g., value > 100 or value < 0).
router.get("/check/:sensorId", (req: Request, res: Response) => {
  const sensorId = Number(req.params.sensorId);
  if (isNaN(sensorId)) {
    res.status(400).json({ error: "Invalid sensorId" });
    return;
  }

  const device = getDeviceById(sensorId);
  if (!device) {
    res.status(404).json({ error: "Sensor device not found" });
    return;
  }

  const readings = getReadingsBySensor(sensorId);
  const alerts: Alert[] = [];
  const now = Date.now();

  if (readings.length === 0) {
    alerts.push({
      sensorId,
      type: "MISSED_HEARTBEAT",
      message: `No readings received at all for sensor ${sensorId}.`,
      timestamp: now
    });
  } else {
    // Sort readings descending by timestamp to find the latest
    const sortedReadings = [...readings].sort((a, b) => b.timestamp - a.timestamp);
    const latestReading = sortedReadings[0];

    // Check missed heartbeat (e.g., 5 minutes = 300,000 ms)
    const fiveMinutesMs = 5 * 60 * 1000;
    if (now - latestReading.timestamp > fiveMinutesMs) {
      alerts.push({
        sensorId,
        type: "MISSED_HEARTBEAT",
        message: `No heartbeat received since ${new Date(latestReading.timestamp).toISOString()}.`,
        timestamp: now
      });
    }

    // Check for out-of-range readings in the last 24 hours
    const oneDayMs = 24 * 60 * 60 * 1000;
    const recentReadings = readings.filter((r: Reading) => now - r.timestamp <= oneDayMs);

    for (const r of recentReadings) {
      if (r.value < 0 || r.value > 100) {
        alerts.push({
          sensorId,
          type: "OUT_OF_RANGE",
          message: `Out-of-range reading detected: ${r.value} at ${new Date(r.timestamp).toISOString()}.`,
          timestamp: r.timestamp
        });
      }
    }
  }

  res.json({
    sensorId,
    checkedAt: now,
    alerts
  });
});

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only intercept POST requests to ingestion endpoints
  const isIngestPath = req.path === "/api/readings" || req.path === "/api/ingest" || req.path.startsWith("/api/readings/");
  if (req.method !== "POST" || !isIngestPath) {
    next();
    return;
  }

  // Extract API key
  let apiKey: string | undefined;

  // 1. Check header x-device-api-key
  const headerKey = req.headers["x-device-api-key"];
  if (typeof headerKey === "string") {
    apiKey = headerKey;
  }

  // 2. Check Authorization header
  if (!apiKey) {
    const authHeader = req.headers["authorization"];
    if (typeof authHeader === "string") {
      if (authHeader.toLowerCase().startsWith("bearer ")) {
        apiKey = authHeader.substring(7).trim();
      } else {
        apiKey = authHeader.trim();
      }
    }
  }

  // 3. Check request body
  if (!apiKey && req.body && typeof req.body === "object") {
    const bodyKey = req.body.apiKey || req.body.api_key;
    if (typeof bodyKey === "string") {
      apiKey = bodyKey;
    }
  }

  if (!apiKey) {
    res.status(401).json({ error: "Unauthorized: Missing device API key" });
    return;
  }

  // Get allowed keys from environment or fallback
  const envKeys = process.env.DEVICE_API_KEYS;
  const allowedKeys = envKeys
    ? envKeys.split(",").map((k) => k.trim())
    : ["dev-key-123", "sensor-key-abc", "test-api-key"];

  if (!allowedKeys.includes(apiKey)) {
    res.status(403).json({ error: "Forbidden: Invalid device API key" });
    return;
  }

  next();
}

import { Router, type Request, type Response, type NextFunction } from "express";
import { getEventById } from "../db/events-table";
