import { middleware as oversellGuard } from "../middleware/oversell-guard";

export const router = Router();

// POST /tickets/purchase
// Body: { eventId: number, userId: number }
router.post(
  "/tickets/purchase",
  oversellGuard,
  (req: Request, res: Response): void => {
    const { eventId, userId } = req.body;

    if (typeof eventId !== "number" || typeof userId !== "number") {
      res.status(400).json({ error: "Missing or invalid eventId or userId" });
      return;
    }

    const event = getEventById(eventId);
    if (!event) {
      res.status(404).json({ error: "Event not found" });
      return;
    }

    // Check current inventory
    const allTickets = getAllTickets();
    const soldTicketsCount = allTickets.filter((t) => t.event_id === eventId).length;

    if (soldTicketsCount >= event.totalTickets) {
      res.status(400).json({ error: "Event is sold out" });
      return;
    }

    // Generate a unique QR code string
    const qrCode = `QR-EVT-${eventId}-USR-${userId}-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;

    try {
      insertTicket(eventId, userId, qrCode);
      res.status(201).json({
        success: true,
        message: "Ticket purchased successfully",
        qrCode: qrCode
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message || "Failed to purchase ticket" });
    }
  }
