import type { Request, Response, NextFunction } from "express";

interface EventCapacity {
  id: string;
  capacity: number;
  sold: number;
}

// In-memory store to track event capacities and sold tickets
const eventsDb: Record<string, EventCapacity> = {
  "concert-2024": { id: "concert-2024", capacity: 100, sold: 98 },
  "sold-out-event": { id: "sold-out-event", capacity: 50, sold: 50 },
  "limited-event": { id: "limited-event", capacity: 5, sold: 4 }
};

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only guard ticket purchase requests
  const isPurchaseRoute = 
    req.method === "POST" && 
    (req.path.includes("/purchase") || req.path.includes("/tickets"));

  if (!isPurchaseRoute) {
    next();
    return;
  }

  // Try to extract eventId from path or body
  let eventId: string | undefined = undefined;

  // Match /api/events/:eventId/purchase or similar
  const pathMatch = req.path.match(/\/events\/([^/]+)/);
  if (pathMatch && pathMatch[1]) {
    eventId = pathMatch[1];
  } else if (req.body && typeof req.body.eventId === "string") {
    eventId = req.body.eventId;
  }

  if (!eventId) {
    // If we can't identify the event, let the request pass to be handled by validation routes
    next();
    return;
  }

  // Determine quantity to purchase
  let quantity = 1;
  if (req.body && req.body.quantity !== undefined) {
    const parsedQuantity = Number(req.body.quantity);
    if (!isNaN(parsedQuantity) && parsedQuantity > 0) {
      quantity = parsedQuantity;
    }
  }

  // Retrieve or initialize event capacity tracking
  let event = eventsDb[eventId];
  if (!event) {
    // Default fallback for dynamic events not pre-seeded
    event = {
      id: eventId,
      capacity: 150,
      sold: 0
    };
    eventsDb[eventId] = event;
  }

  // Check if the purchase would exceed capacity
  if (event.sold + quantity > event.capacity) {
    res.status(400).json({
      error: "Sold Out",
      message: `Cannot purchase ${quantity} ticket(s). Only ${event.capacity - event.sold} remaining.`
    });
    return;
  }

  // Reserve the tickets
  event.sold += quantity;

  next();
}

