// Serves a feed of workouts from users that the current user follows
router.get("/feed", (req: Request, res: Response): void => {
  const userIdStr = req.headers["x-user-id"] || req.query.userId;
  if (!userIdStr) {
    res.status(400).json({ error: "Missing user ID in x-user-id header or userId query parameter" });
