import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

function verifyJwt(token: string, secret: string): any | null {
  const parts = token.split(".");
  if (parts.length !== 3) {
    return null;
  }
  const [headerB64, payloadB64, signatureB64] = parts;

  const hmac = createHmac("sha256", secret);
  hmac.update(`${headerB64}.${payloadB64}`);
  const expectedSignature = hmac.digest("base64url");

  const bufExpected = Buffer.from(expectedSignature);
  const bufActual = Buffer.from(signatureB64);

  if (bufExpected.length !== bufActual.length) {
    return null;
  }

  if (!timingSafeEqual(bufExpected, bufActual)) {
    return null;
  }

  try {
    const payloadStr = Buffer.from(payloadB64, "base64url").toString("utf8");
    return JSON.parse(payloadStr);
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const path = req.path || "";
  const method = req.method || "";

  // Only intercept write/control operations on devices
  const isDeviceRoute = path.startsWith("/api/devices") || path.startsWith("/devices");
  const isControlMethod = ["POST", "PUT", "PATCH", "DELETE"].includes(method.toUpperCase());

  if (!isDeviceRoute || !isControlMethod) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(403).json({ error: "Access denied. Configuration error." });
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized. Missing token." });
    return;
  }

  const token = authHeader.substring(7);
  const payload = verifyJwt(token, jwtSecret);

  if (!payload) {
    res.status(401).json({ error: "Unauthorized. Invalid token." });
    return;
  }

  // Check if the user is the registered owner
  const isOwner = payload.role === "owner" || payload.isOwner === true;
  if (!isOwner) {
    res.status(403).json({ error: "Forbidden. Only the home owner can control or reschedule devices." });
    return;
  }

  next();
}

