      insertClaimDecision(parsedAdjusterId, String(decision), String(reasonText), claimId);
      updateClaimStatus(claimId, String(decision));

      res.status(201).json({ message: "Decision recorded and claim status updated" });
    } catch (error: any) {
      res.status(500).json({ error: error.message || "Failed to record decision" });
    }
  }
);

import { Router, type Request, type Response } from "express";
import { getClaimById, updateClaimStatus } from "../db/claims-table";
import { insertClaimDecision, getClaimDecisionsByClaimId } from "../db/claim-decisions-table";
import { middleware as reasonRequiredGuard } from "../middleware/reason-required-guard";

export const router = Router();

// POST /decisions
// Expects body: { claimId: number, adjusterId: number, decision: string, reasonText: string }
router.post(
  "/",
  reasonRequiredGuard,
  (req: Request, res: Response): void => {
    const { claimId, adjusterId, decision, reasonText } = req.body;

    if (!claimId || !adjusterId || !decision) {
      res.status(400).json({ error: "Missing required fields: claimId, adjusterId, decision" });
      return;
    }

    const claimIdNum = Number(claimId);
    const adjusterIdNum = Number(adjusterId);
    const decisionStr = String(decision).trim();
    const reasonStr = reasonText ? String(reasonText).trim() : "";

    if (isNaN(claimIdNum) || isNaN(adjusterIdNum)) {
      res.status(400).json({ error: "claimId and adjusterId must be valid numbers" });
      return;
    }

    const claim = getClaimById(claimIdNum);
    if (!claim) {
      res.status(404).json({ error: `Claim with ID ${claimIdNum} not found` });
      return;
    }

    // Record the decision
    insertClaimDecision(adjusterIdNum, decisionStr, reasonStr, claimIdNum);

    // Update the claim status to match the decision (e.g., "Approved" or "Denied")
    updateClaimStatus(claimIdNum, decisionStr);

    res.status(201).json({
      message: "Decision recorded successfully",
      claimId: claimIdNum,
      decision: decisionStr
    });
  }
);

// GET /decisions/claim/:claimId
router.get(
  "/claim/:claimId",
  (req: Request, res: Response): void => {
    const claimIdNum = Number(req.params.claimId);
    if (isNaN(claimIdNum)) {
      res.status(400).json({ error: "Invalid claimId parameter" });
      return;
    }

    const decisions = getClaimDecisionsByClaimId(claimIdNum);
    res.status(200).json(decisions);
  }
);

import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const method = req.method;
  const path = req.path;

  // Only intercept POST, PUT, or PATCH requests targeting claim decision or finalisation endpoints
  const isFinaliseRoute = /\/claims\/[^/]+\/(decision|finalise|finalize)/i.test(path);
  const isWriteMethod = ["POST", "PUT", "PATCH"].includes(method);

  if (!isWriteMethod || !isFinaliseRoute) {
    next();
    return;
  }

  const body = req.body;
  if (!body || typeof body !== "object") {
    res.status(400).json({ error: "A documented reason is required to finalise a claim decision." });
    return;
  }

  const reason = body.reason;
  if (typeof reason !== "string" || reason.trim() === "") {
    res.status(400).json({ error: "A documented reason is required to finalise a claim decision." });
    return;
  }

  next();
}

