import { Router, type Request, type Response } from "express";
import { getCarById, getAllCars } from "../db/cars-table";
import { getBookingsByCarId, insertBooking } from "../db/bookings-table";

export const router = Router();

// Helper to check date overlap
function isOverlapping(
  start1: string,
  end1: string,
  start2: string,
  end2: string
): boolean {
  const s1 = new Date(start1).getTime();
  const e1 = new Date(end1).getTime();
  const s2 = new Date(start2).getTime();
  const e2 = new Date(end2).getTime();

  return s1 <= e2 && s2 <= e1;
}

// GET /api/rentals/availability
// Query params: startDate, endDate
router.get("/availability", (req: Request, res: Response): void => {
  const { startDate, endDate } = req.query;

  if (!startDate || !endDate) {
    res.status(400).json({ error: "startDate and endDate query parameters are required" });
    return;
  }

  const startStr = String(startDate);
  const endStr = String(endDate);

  if (isNaN(Date.parse(startStr)) || isNaN(Date.parse(endStr))) {
    res.status(400).json({ error: "Invalid date format" });
    return;
  }

  if (new Date(startStr) > new Date(endStr)) {
    res.status(400).json({ error: "startDate cannot be after endDate" });
    return;
  }

  const allCars = getAllCars();
  const availableCars = allCars.filter((car) => {
    const bookings = getBookingsByCarId(car.id);
    const hasOverlap = bookings.some((booking) =>
      isOverlapping(booking.startDate, booking.endDate, startStr, endStr)
    );
    return !hasOverlap;
  });

  res.json(availableCars);
});

// POST /api/rentals/bookings
// Body: carId, customerId, startDate, endDate
router.post("/bookings", (req: Request, res: Response): void => {
  const { carId, customerId, startDate, endDate } = req.body;

  if (carId === undefined || customerId === undefined || !startDate || !endDate) {
    res.status(400).json({ error: "Missing required fields: carId, customerId, startDate, endDate" });
    return;
  }

  const parsedCarId = Number(carId);
  const parsedCustomerId = Number(customerId);
  const startStr = String(startDate);
  const endStr = String(endDate);

  if (isNaN(parsedCarId) || isNaN(parsedCustomerId)) {
    res.status(400).json({ error: "carId and customerId must be valid numbers" });
    return;
  }

  if (isNaN(Date.parse(startStr)) || isNaN(Date.parse(endStr))) {
    res.status(400).json({ error: "Invalid date format" });
    return;
  }

  if (new Date(startStr) > new Date(endStr)) {
    res.status(400).json({ error: "startDate cannot be after endDate" });
    return;
  }

  const car = getCarById(parsedCarId);
  if (!car) {
    res.status(404).json({ error: "Car not found" });
    return;
  }

  const existingBookings = getBookingsByCarId(parsedCarId);
  const hasOverlap = existingBookings.some((booking) =>
    isOverlapping(booking.startDate, booking.endDate, startStr, endStr)
  );

  if (hasOverlap) {
    res.status(409).json({ error: "Car is already booked for the requested dates" });
    return;
  }

  insertBooking(parsedCarId, parsedCustomerId, startStr, endStr);
  res.status(201).json({
    message: "Booking created successfully",
    booking: {
      carId: parsedCarId,
      customerId: parsedCustomerId,
      startDate: startStr,
      endDate: endStr
    }
  });
});

