import { Router, type Request, type Response } from "express";
import { getAllBuilds, type BuildRow } from "../db/builds-table";

export const router = Router();

// Mock Slack Webhook URL or endpoint for demonstration purposes
// In a real application, this would be loaded from process.env.SLACK_WEBHOOK_URL
let slackWebhookUrl = process.env.SLACK_WEBHOOK_URL || "https://hooks.slack.com/services/mock/webhook";

/**
 * POST /api/slack/notify-failure
 * Checks the latest build for the main branch. If it failed, posts a notification to Slack.
 */
router.post("/api/slack/notify-failure", async (req: Request, res: Response): Promise<void> => {
  try {
    const builds: BuildRow[] = getAllBuilds();

    // Filter for main branch builds
    const mainBuilds = builds.filter((b: BuildRow) => b.branch === "main");

    if (mainBuilds.length === 0) {
      res.status(404).json({ error: "No builds found for main branch" });
      return;
    }

    // Sort by timestamp descending to get the latest build
    const latestMainBuild = mainBuilds.sort((a: BuildRow, b: BuildRow) => b.timestamp - a.timestamp)[0];

    if (latestMainBuild.status.toLowerCase() !== "failed") {
      res.status(200).json({
        message: `Latest main branch build #${latestMainBuild.id} is not failed (status: ${latestMainBuild.status}). No notification sent.`
      });
      return;
    }

    // Construct Slack message payload
    const slackPayload = {
      text: `🚨 *Build Failure Alert* 🚨\n*Repository:* ${latestMainBuild.repo}\n*Branch:* ${latestMainBuild.branch}\n*Build ID:* ${latestMainBuild.id}\n*Status:* ${latestMainBuild.status.toUpperCase()}\n*Time:* ${new Date(latestMainBuild.timestamp).toISOString()}`
    };

    // Send notification to Slack webhook
    const response = await fetch(slackWebhookUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(slackPayload)
    });

    if (!response.ok) {
      throw new Error(`Slack API responded with status ${response.status}`);
    }

    res.status(200).json({
      message: "Slack notification sent successfully",
      buildId: latestMainBuild.id,
      status: latestMainBuild.status
    });
  } catch (error: any) {
    res.status(500).json({
      error: "Failed to send Slack notification",
      details: error instanceof Error ? error.message : String(error)
    });
  }
});

