// GET /standings
router.get("/standings", (req: Request, res: Response): void => {
  try {
    const teams = getTeams();
    const games = getGames();

    const standingsMap: { [teamName: string]: StandingsRow } = {};

    // Initialize standings for all registered teams
    teams.forEach((team: Team) => {
      standingsMap[team.name] = {
        teamName: team.name,
        played: 0,
        wins: 0,
        losses: 0,
        draws: 0,
        points: 0,
        goalsFor: 0,
        goalsAgainst: 0
      };
    });

    // Process each game
    games.forEach((game: Game) => {
      // Ensure teams exist in standings map (even if not in teams table, to avoid crashes)
      if (!standingsMap[game.homeTeam]) {
        standingsMap[game.homeTeam] = {
          teamName: game.homeTeam,
          played: 0,
          wins: 0,
          losses: 0,
          draws: 0,
          points: 0,
          goalsFor: 0,
          goalsAgainst: 0
        };
      }
      if (!standingsMap[game.awayTeam]) {
        standingsMap[game.awayTeam] = {
          teamName: game.awayTeam,
          played: 0,
          wins: 0,
          losses: 0,
          draws: 0,
          points: 0,
          goalsFor: 0,
          goalsAgainst: 0
        };
      }

      const home = standingsMap[game.homeTeam];
      const away = standingsMap[game.awayTeam];

      home.played += 1;
      away.played += 1;
      home.goalsFor += game.homeScore;
      home.goalsAgainst += game.awayScore;
      away.goalsFor += game.awayScore;
      away.goalsAgainst += game.homeScore;

      if (game.homeScore > game.awayScore) {
        home.wins += 1;
        home.points += 3;
        away.losses += 1;
      } else if (game.awayScore > game.homeScore) {
        away.wins += 1;
        away.points += 3;
        home.losses += 1;
      } else {
        home.draws += 1;
        home.points += 1;
        away.draws += 1;
        away.points += 1;
      }
    });

    // Convert to array and sort by points (descending), then goal difference (descending)
    const standingsList = Object.values(standingsMap).sort((a: StandingsRow, b: StandingsRow) => {
      if (b.points !== a.points) {
        return b.points - a.points;
      }
      const aDiff = a.goalsFor - a.goalsAgainst;
      const bDiff = b.goalsFor - b.goalsAgainst;
      return bDiff - aDiff;
    });

    res.json(standingsList);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Failed to compute standings" });
  }
});

