  const existingReservations = getReservations();
  const bookedTables = existingReservations
    .filter((r: Reservation) => r.timeSlot === timeSlot)
    .map((r: Reservation) => r.tableAssignment);

  // Find tables that can accommodate the party size and are not booked
  const suitableTables = TABLES.filter((t) => t.capacity >= partySize);
  for (const table of suitableTables) {
    if (!bookedTables.includes(table.id)) {
      return table.id;
    }
  }
  return null;
}

// POST /reservations - Create a booking
router.post("/", (req: Request, res: Response): void => {
  const { partySize, timeSlot, guestContactInfo } = req.body;

  if (!partySize || !timeSlot || !guestContactInfo) {
    res.status(400).json({ error: "Missing required fields: partySize, timeSlot, guestContactInfo" });
    return;
  }

  const size = Number(partySize);
  if (isNaN(size) || size <= 0) {
    res.status(400).json({ error: "partySize must be a positive number" });
    return;
  }

  const tableAssignment = findAvailableTable(timeSlot, size);
  if (!tableAssignment) {
    res.status(409).json({ error: "No available tables for the requested time slot and party size" });
    return;
  }

  try {
    insertReservation(size, timeSlot, tableAssignment, guestContactInfo);
    // Retrieve the newly created reservation (usually the last one)
    const all = getReservations();
    const created = all[all.length - 1];
    res.status(201).json(created);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Failed to create reservation" });
  }
});

// GET /reservations - Get all bookings
router.get("/", (req: Request, res: Response): void => {
  try {
    const reservations = getReservations();
    res.status(200).json(reservations);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Failed to retrieve reservations" });
