});

// GET /reservations/:id - Get booking by ID
router.get("/:id", (req: Request, res: Response): void => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).json({ error: "Invalid reservation ID" });
    return;
  }

  const reservation = getReservationById(id);
  if (!reservation) {
    res.status(404).json({ error: "Reservation not found" });
    return;
  }

  res.status(200).json(reservation);
});

// PUT /reservations/:id - Update a booking
router.put("/:id", (req: Request, res: Response): void => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).json({ error: "Invalid reservation ID" });
    return;
  }

  const existing = getReservationById(id);
  if (!existing) {
    res.status(404).json({ error: "Reservation not found" });
    return;
  }

  const { partySize, timeSlot, guestContactInfo } = req.body;
  const updatedPartySize = partySize !== undefined ? Number(partySize) : existing.partySize;
  const updatedTimeSlot = timeSlot !== undefined ? timeSlot : existing.timeSlot;
  const updatedContact = guestContactInfo !== undefined ? guestContactInfo : existing.guestContactInfo;

  if (isNaN(updatedPartySize) || updatedPartySize <= 0) {
    res.status(400).json({ error: "partySize must be a positive number" });
    return;
  }

  // If time slot or party size changed, we need to re-verify table availability
  let tableAssignment = existing.tableAssignment;
  if (updatedTimeSlot !== existing.timeSlot || updatedPartySize !== existing.partySize) {
    // Temporarily ignore current reservation to check availability
    const allReservations = getReservations();
    const bookedTables = allReservations
      .filter((r: Reservation) => r.timeSlot === updatedTimeSlot && r.id !== id)
      .map((r: Reservation) => r.tableAssignment);

    const suitableTables = TABLES.filter((t) => t.capacity >= updatedPartySize);
    let foundTable: string | null = null;
    for (const table of suitableTables) {
      if (!bookedTables.includes(table.id)) {
        foundTable = table.id;
        break;
      }
    }

    if (!foundTable) {
      res.status(409).json({ error: "No available tables for the updated time slot and party size" });
      return;
    }
    tableAssignment = foundTable;
  }

  try {
    updateReservation(id, updatedPartySize, updatedTimeSlot, tableAssignment, updatedContact);
    const updated = getReservationById(id);
    res.status(200).json(updated);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Failed to update reservation" });
  }
});

// DELETE /reservations/:id - Cancel a booking
router.delete("/:id", (req: Request, res: Response): void => {
  const id = Number(req.params.id);
  if (isNaN(id)) {
    res.status(400).json({ error: "Invalid reservation ID" });
    return;
  }

  const existing = getReservationById(id);
  if (!existing) {
    res.status(404).json({ error: "Reservation not found" });
    return;
  }

  try {
    deleteReservation(id);
    res.status(200).json({ message: "Reservation successfully cancelled" });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Failed to delete reservation" });
  }
});

import { Router, type Request, type Response } from "express";
import { getRouteById, getRoutes, type Route } from "../db/routes-table";
import {
  insertRideRequest,
  getRideRequest,
  getAllRideRequests,
  updateApprovalStatus,
  deleteRideRequest,
  type RideRequest
} from "../db/ride-requests-table";

export const router = Router();

// GET /api/carpools - List all routes with their associated ride requests
router.get("/", (req: Request, res: Response): void => {
  try {
    const routes = getRoutes();
    const requests = getAllRideRequests();

    const result = routes.map((route: Route) => {
      const routeRequests = requests.filter((reqItem: RideRequest) => reqItem.routeId === route.id);
      return {
        ...route,
        requests: routeRequests
      };
    });

    res.status(200).json(result);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// POST /api/carpools/request - Request a seat on a route
router.post("/request", (req: Request, res: Response): void => {
  try {
    const { riderId, routeId } = req.body;

    if (typeof riderId !== "number" || typeof routeId !== "number") {
      res.status(400).json({ error: "riderId and routeId must be numbers" });
      return;
    }

    const route = getRouteById(routeId);
    if (!route) {
      res.status(404).json({ error: "Route not found" });
      return;
    }

    const existing = getRideRequest(riderId, routeId);
    if (existing) {
      res.status(400).json({ error: "Ride request already exists for this route" });
      return;
    }

    // Check seat availability
    const allRequests = getAllRideRequests();
    const approvedCount = allRequests.filter(
      (r: RideRequest) => r.routeId === routeId && r.approvalStatus === "approved"
    ).length;

    if (approvedCount >= route.totalSeats) {
      res.status(400).json({ error: "No seats available on this route" });
      return;
    }

    insertRideRequest(riderId, routeId, "pending");
    res.status(201).json({ message: "Ride request submitted successfully", status: "pending" });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// PUT /api/carpools/decide - Approve or decline a ride request
router.put("/decide", (req: Request, res: Response): void => {
  try {
    const { riderId, routeId, approvalStatus } = req.body;

    if (typeof riderId !== "number" || typeof routeId !== "number" || typeof approvalStatus !== "string") {
      res.status(400).json({ error: "riderId, routeId, and approvalStatus are required" });
      return;
    }

    if (approvalStatus !== "approved" && approvalStatus !== "declined" && approvalStatus !== "pending") {
      res.status(400).json({ error: "Invalid approvalStatus. Must be approved, declined, or pending" });
      return;
    }

    const route = getRouteById(routeId);
    if (!route) {
      res.status(404).json({ error: "Route not found" });
      return;
    }

    const existing = getRideRequest(riderId, routeId);
    if (!existing) {
      res.status(404).json({ error: "Ride request not found" });
      return;
    }

    if (approvalStatus === "approved") {
      const allRequests = getAllRideRequests();
      const approvedCount = allRequests.filter(
        (r: RideRequest) => r.routeId === routeId && r.approvalStatus === "approved"
      ).length;

      if (approvedCount >= route.totalSeats && existing.approvalStatus !== "approved") {
        res.status(400).json({ error: "Cannot approve. Route is already full" });
        return;
      }
    }

    updateApprovalStatus(riderId, routeId, approvalStatus);
    res.status(200).json({ message: `Ride request status updated to ${approvalStatus}` });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

// DELETE /api/carpools/request - Cancel a ride request
router.delete("/request", (req: Request, res: Response): void => {
  try {
    const riderId = Number(req.query.riderId);
    const routeId = Number(req.query.routeId);

    if (isNaN(riderId) || isNaN(routeId)) {
      res.status(400).json({ error: "riderId and routeId query parameters must be valid numbers" });
      return;
    }

    const existing = getRideRequest(riderId, routeId);
    if (!existing) {
      res.status(404).json({ error: "Ride request not found" });
      return;
    }

    deleteRideRequest(riderId, routeId);
    res.status(200).json({ message: "Ride request cancelled successfully" });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
});

