import { Router, type Request, type Response } from "express";
import { getMemberById } from "../db/members-table";
import { insertCheckIn } from "../db/check-ins-table";
import { middleware as expiryGuard } from "../middleware/expiry-guard";

export const router = Router();

// POST /api/check-in
// Validates a member's code (id) and membership status before allowing check-in.
router.post(
  "/api/check-in",
  expiryGuard,
  (req: Request, res: Response): void => {
    const { memberId } = req.body;

    if (memberId === undefined || memberId === null) {
      res.status(400).json({ error: "Missing memberId" });
      return;
    }

    const parsedId = Number(memberId);
    if (isNaN(parsedId)) {
      res.status(400).json({ error: "Invalid memberId format" });
      return;
    }

    const member = getMemberById(parsedId);
    if (!member) {
      res.status(404).json({ error: "Member not found" });
      return;
    }

    const todayStr = new Date().toISOString().split("T")[0];
    const expiryStr = member.expiryDate;

    if (expiryStr < todayStr) {
      insertCheckIn(parsedId, "REJECTED_EXPIRED");
      res.status(403).json({
        status: "REJECTED",
        reason: "Membership expired",
        expiryDate: expiryStr
      });
      return;
    }

    insertCheckIn(parsedId, "APPROVED");
    res.status(200).json({
      status: "APPROVED",
      memberId: parsedId,
      plan: member.plan,
      expiryDate: expiryStr
    });
  }
);

