import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

function safeByteCompare(a: string, b: string): boolean {
  try {
    const bufA = Buffer.from(a, "utf8");
    const bufB = Buffer.from(b, "utf8");
    if (bufA.length !== bufB.length) {
      return false;
    }
    return timingSafeEqual(bufA, bufB);
  } catch {
    return false;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const path = req.path.toLowerCase();
  const isCheckIn = req.method === "POST" && (path.includes("check-in") || path.includes("checkin"));

  if (!isCheckIn) {
    next();
    return;
  }

  let expiryValue: string | number | undefined = undefined;

  // 1. Check request body for expiry fields
  if (req.body && typeof req.body === "object") {
    const body = req.body as Record<string, unknown>;
    if (typeof body.expiryDate === "string" || typeof body.expiryDate === "number") {
      expiryValue = body.expiryDate;
    } else if (typeof body.expiry === "string" || typeof body.expiry === "number") {
      expiryValue = body.expiry;
    } else if (typeof body.membershipExpiry === "string" || typeof body.membershipExpiry === "number") {
      expiryValue = body.membershipExpiry;
    }
  }

  // 2. Check Authorization header for JWT if expiry is not in body
  const authHeader = req.headers.authorization;
  if (!expiryValue && authHeader && authHeader.startsWith("Bearer ")) {
    const token = authHeader.substring(7).trim();
    const secret = process.env.JWT_SECRET;

    if (!secret) {
      res.status(401).json({ error: "Unauthorized: JWT_SECRET is not configured" });
      return;
    }

    const parts = token.split(".");
    if (parts.length === 3) {
      const [headerB64, payloadB64, signatureB64] = parts;
      const dataToSign = `${headerB64}.${payloadB64}`;

      const hmac = createHmac("sha256", secret);
      hmac.update(dataToSign);
      const expectedSignature = hmac.digest("base64url");

      if (safeByteCompare(signatureB64, expectedSignature)) {
        try {
          const payloadStr = Buffer.from(payloadB64, "base64url").toString("utf8");
          const payload = JSON.parse(payloadStr) as Record<string, unknown>;

          if (typeof payload.membershipExpiry === "string" || typeof payload.membershipExpiry === "number") {
            expiryValue = payload.membershipExpiry;
          } else if (typeof payload.expiry === "string" || typeof payload.expiry === "number") {
            expiryValue = payload.expiry;
          } else if (typeof payload.expiryDate === "string" || typeof payload.expiryDate === "number") {
            expiryValue = payload.expiryDate;
          }
        } catch {
          // Ignore JSON parsing errors and proceed
        }
      } else {
        res.status(401).json({ error: "Unauthorized: Invalid token signature" });
        return;
      }
    }
  }

  // 3. Validate expiry date if found
  if (expiryValue !== undefined) {
    const expiryDate = new Date(expiryValue);
    if (!isNaN(expiryDate.getTime())) {
      if (expiryDate.getTime() < Date.now()) {
        res.status(403).json({ error: "Membership has expired" });
        return;
      }
    }
  }

  next();
}

