import { createHmac, timingSafeEqual } from "node:crypto";
import type { Request, Response, NextFunction } from "express";

// Simple mock database of session notes to allow the guard to perform real checks
export interface SessionNote {
  id: string;
  sessionId: string;
  therapistId: string;
  clientId: string;
  content: string;
}

export const mockNotesDb: Record<string, SessionNote> = {
  "note-1": {
    id: "note-1",
    sessionId: "session-1",
    therapistId: "therapist-123",
    clientId: "client-456",
    content: "Client is making good progress with cognitive behavioral exercises."
  }
};

function verifyJwt(token: string): { userId: string; role: string } | null {
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    return null;
  }

  const parts = token.split(".");
  if (parts.length !== 3) {
    return null;
  }

  const [headerB64, payloadB64, signatureB64] = parts;

  try {
    const hmac = createHmac("sha256", secret);
    hmac.update(`${headerB64}.${payloadB64}`);
    const expectedSignature = hmac.digest("base64url");

    const sigBuffer = Buffer.from(signatureB64);
    const expectedBuffer = Buffer.from(expectedSignature);

    if (sigBuffer.length !== expectedBuffer.length) {
      return null;
    }

    if (!timingSafeEqual(sigBuffer, expectedBuffer)) {
      return null;
    }

    const payloadStr = Buffer.from(payloadB64, "base64url").toString("utf8");
    const payload = JSON.parse(payloadStr);
    if (payload && typeof payload === "object" && "userId" in payload) {
      return payload as { userId: string; role: string };
    }
    return null;
  } catch {
    return null;
  }
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Only intercept requests targeting session notes
  const isNotesPath = req.path.includes("/notes");
  if (!isNotesPath) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing or invalid authorization header" });
    return;
  }

  const token = authHeader.substring(7);
  const decoded = verifyJwt(token);
  if (!decoded) {
    res.status(401).json({ error: "Unauthorized: Invalid token signature or payload" });
    return;
  }

  // Extract note ID from path if present (e.g., /api/notes/note-1)
  const pathParts = req.path.split("/");
  const notesIndex = pathParts.indexOf("notes");
  const noteId = notesIndex !== -1 && pathParts[notesIndex + 1] ? pathParts[notesIndex + 1] : null;

  let therapistId: string | null = null;
  let clientId: string | null = null;

  if (noteId && mockNotesDb[noteId]) {
    const note = mockNotesDb[noteId];
    therapistId = note.therapistId;
    clientId = note.clientId;
  } else {
    // Fallback to checking request body or query parameters for creation/listing filters
    const bodyTherapist = req.body && typeof req.body.therapistId === "string" ? req.body.therapistId : null;
    const bodyClient = req.body && typeof req.body.clientId === "string" ? req.body.clientId : null;
    const queryTherapist = req.query && typeof req.query.therapistId === "string" ? req.query.therapistId : null;
    const queryClient = req.query && typeof req.query.clientId === "string" ? req.query.clientId : null;

    therapistId = bodyTherapist || queryTherapist;
    clientId = bodyClient || queryClient;
  }

  // If we cannot determine the therapist or client for this notes request, restrict access to be safe
  if (!therapistId && !clientId) {
    res.status(403).json({ error: "Forbidden: Access to notes is restricted to the assigned therapist and client" });
    return;
  }

  const currentUserId = decoded.userId;
  const isAssignedTherapist = therapistId !== null && currentUserId === therapistId;
  const isAssignedClient = clientId !== null && currentUserId === clientId;

  if (isAssignedTherapist || isAssignedClient) {
    next();
  } else {
    res.status(403).json({ error: "Forbidden: Session notes are only visible to the assigned therapist and client" });
  }
}

