// POST /api/inventory/movements - Log a stock movement and update stock levels
router.post("/movements", (req: Request, res: Response): void => {
  try {
    const { sku, productId, quantity, movementType, locationId, reorderThreshold } = req.body;

    if (!sku || typeof productId !== "number" || typeof quantity !== "number" || !movementType || typeof locationId !== "number") {
      res.status(400).json({ error: "Missing or invalid required fields: sku, productId, quantity, movementType, locationId" });
      return;
    }

    if (movementType !== "in" && movementType !== "out") {
      res.status(400).json({ error: "movementType must be 'in' or 'out'" });
      return;
    }

    if (quantity <= 0) {
      res.status(400).json({ error: "quantity must be a positive number" });
      return;
    }

    // Log the movement
    logStockMovement(productId, quantity, movementType);

    // Retrieve existing stock level or default to 0
    const existingLevel = getStockLevelBySku(sku);
    const currentQty = existingLevel ? existingLevel.currentQuantity : 0;
    const threshold = typeof reorderThreshold === "number" ? reorderThreshold : (existingLevel ? existingLevel.reorderThreshold : 10);

    // Calculate new quantity
    let newQty = currentQty;
    if (movementType === "in") {
      newQty += quantity;
    } else {
      newQty -= quantity;
    }

    // Update stock level
    updateStockLevel(sku, locationId, newQty, threshold);

    const updatedLevel = getStockLevelBySku(sku);
    const isBelowReorder = updatedLevel ? updatedLevel.currentQuantity < updatedLevel.reorderThreshold : false;

    res.status(200).json({
      message: "Stock movement processed successfully",
      stockLevel: updatedLevel,
      reorderAlert: isBelowReorder
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Failed to process stock movement" });
  }
});

