import type { Request, Response, NextFunction } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const isApprovalRoute =
    (req.method === "POST" || req.method === "PUT" || req.method === "PATCH") &&
    (req.path.includes("/approve") ||
      req.path.includes("/reject") ||
      req.path.includes("/status") ||
      (req.body && (req.body.status === "approved" || req.body.status === "rejected")));

  if (!isApprovalRoute) {
    next();
    return;
  }

  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({ error: "Unauthorized: Missing token" });
    return;
  }

  const token = authHeader.substring(7);
  const parts = token.split(".");
  if (parts.length !== 3) {
    res.status(401).json({ error: "Unauthorized: Invalid token format" });
    return;
  }

  const [headerB64, payloadB64, signatureB64] = parts;
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(401).json({ error: "Unauthorized: JWT secret not configured" });
    return;
  }

  try {
    const hmac = createHmac("sha256", secret);
    hmac.update(`${headerB64}.${payloadB64}`);
    const expectedSignature = hmac.digest("base64url");

    const sigBuffer = Buffer.from(signatureB64, "base64url");
    const expBuffer = Buffer.from(expectedSignature, "base64url");

    if (sigBuffer.length !== expBuffer.length || !timingSafeEqual(sigBuffer, expBuffer)) {
      res.status(401).json({ error: "Unauthorized: Invalid signature" });
      return;
    }

    const payloadStr = Buffer.from(payloadB64, "base64url").toString("utf8");
    const payload = JSON.parse(payloadStr);

    const directReports: unknown = payload.directReports || (payload.user && payload.user.directReports);
    if (!Array.isArray(directReports)) {
      res.status(403).json({ error: "Forbidden: No direct reports configured for this manager" });
      return;
    }

    const employeeId = req.body?.employeeId || req.body?.submitterId;
    if (!employeeId) {
      res.status(400).json({ error: "Bad Request: Missing employeeId or submitterId in request body" });
      return;
    }

    const isDirectReport = directReports.some(
      (reportId: unknown) => String(reportId) === String(employeeId)
    );

    if (!isDirectReport) {
      res.status(403).json({ error: "Forbidden: You can only approve or reject expenses from your own direct reports" });
      return;
    }

    next();
  } catch (err) {
    res.status(401).json({ error: "Unauthorized: Invalid token" });
  }
}

