export const router = Router();

// Helper to compute weekly hours from clock events
function computeWeeklyHours(events: ClockEvent[]): number {
  // Sort events chronologically
  const sorted = [...events].sort((a, b) => {
    return new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime();
  });

  let totalHours = 0;
  let lastInTime: number | null = null;

  for (const event of sorted) {
    if (event.eventType === "in") {
      lastInTime = new Date(event.timestamp).getTime();
    } else if (event.eventType === "out" && lastInTime !== null) {
      const outTime = new Date(event.timestamp).getTime();
      const diffMs = outTime - lastInTime;
      if (diffMs > 0) {
        totalHours += diffMs / (1000 * 60 * 60);
      }
      lastInTime = null;
    }
  }

  return Math.round(totalHours * 100) / 100;
}

