import { Router, type Request, type Response } from "express";
import {
  getClockEventsByEmployeeId,
  db,
  type ClockEvent
 } from "../db/clock-events-table";
import { middleware } from "../middleware/approved-only-payroll-guard";

export const router = Router();

const exportHandler = (req: Request, res: Response): void => {
  try {
    let employeeIds: number[] = [];
    if (req.query.employeeIds) {
      const idsStr = req.query.employeeIds as string;
      employeeIds = idsStr
        .split(",")
        .map((id: string) => Number(id.trim()))
        .filter((id: number) => !isNaN(id));
    } else {
      try {
        const stmt = db.prepare("SELECT DISTINCT employeeId FROM clock_events");
        const rows = stmt.all() as { employeeId: number }[];
        employeeIds = rows.map((r: { employeeId: number }) => r.employeeId);
      } catch (e) {
        employeeIds = [];
      }
    }

    const payrollRecords: Array<{
      employeeId: number;
      totalHours: number;
      status: string;
    }> = [];

    for (const empId of employeeIds) {
      const events = getClockEventsByEmployeeId(empId);
      const sortedEvents = [...events].sort((a: ClockEvent, b: ClockEvent) => {
        return new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime();
      });

      let totalMs = 0;
      let lastInTime: number | null = null;

      for (const event of sortedEvents) {
        if (event.eventType === "in") {
          lastInTime = new Date(event.timestamp).getTime();
        } else if (event.eventType === "out" && lastInTime !== null) {
          totalMs += (new Date(event.timestamp).getTime() - lastInTime);
          lastInTime = null;
        }
      }

      const totalHours = Number((totalMs / (1000 * 60 * 60)).toFixed(2));
      payrollRecords.push({
        employeeId: empId,
        totalHours,
        status: "Approved"
      });
    }

    let csvContent = "EmployeeID,TotalHoursWorked,Status\n";
    for (const record of payrollRecords) {
      csvContent += `${record.employeeId},${record.totalHours},${record.status}\n`;
    }

    res.setHeader("Content-Type", "text/csv");
    res.setHeader("Content-Disposition", "attachment; filename=payroll-export.csv");
    res.status(200).send(csvContent);
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal Server Error" });
  }
};

router.get("/", middleware, exportHandler);
router.get("/export", middleware, exportHandler);

import type { Request, Response, NextFunction } from "express";

interface Timesheet {
  id?: string | number;
  status?: string;
  approved?: boolean;
}

export function middleware(req: Request, res: Response, next: NextFunction): void {
  const path = req.path.toLowerCase();

  // Only intercept payroll export endpoints
  const isPayrollExport = path.includes("/payroll/export") || path.includes("/payroll-export");
  if (!isPayrollExport) {
    next();
    return;
  }

  // If there is a request body, validate that any timesheets included are approved
  if (req.body) {
    // Case 1: The body itself is an array of timesheets
    if (Array.isArray(req.body)) {
      const hasUnapproved = req.body.some((ts: any) => {
        if (ts && typeof ts === "object") {
          return ts.status !== "approved" && ts.approved !== true;
        }
        return false;
      });

      if (hasUnapproved) {
        res.status(400).json({
          error: "Cannot export payroll: One or more timesheets are not approved."
        });
        return;
      }
    }

    // Case 2: The body contains a timesheets array property
    if (req.body.timesheets && Array.isArray(req.body.timesheets)) {
      const hasUnapproved = req.body.timesheets.some((ts: any) => {
        if (ts && typeof ts === "object") {
          return ts.status !== "approved" && ts.approved !== true;
        }
        return false;
      });

      if (hasUnapproved) {
        res.status(400).json({
          error: "Cannot export payroll: One or more timesheets are not approved."
        });
        return;
      }
    }
  }

  next();
}

import { Router, type Request, type Response } from "express";
import {
  insertReservation,
  getReservationsByDate,
  getReservationByEmployeeAndDate,
  type Reservation
} from "../db/reservations-table";

export const router = Router();

// Total spots available in the building
const TOTAL_SPOTS = 50;

// GET /api/parking/status?date=YYYY-MM-DD
router.get("/status", (req: Request, res: Response): void => {
  const date = req.query.date as string;
  if (!date) {
    res.status(400).json({ error: "Missing date parameter" });
    return;
  }

  try {
    const reservations = getReservationsByDate(date);
    const reservedCount = reservations.length;
    const availableCount = Math.max(0, TOTAL_SPOTS - reservedCount);

    res.json({
      date,
      totalSpots: TOTAL_SPOTS,
      reservedSpotsCount: reservedCount,
      availableSpotsCount: availableCount,
      reservations
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal server error" });
  }
});

// POST /api/parking/reserve
router.post("/reserve", (req: Request, res: Response): void => {
  const { employeeId, date } = req.body;

  if (employeeId === undefined || !date) {
    res.status(400).json({ error: "Missing employeeId or date" });
    return;
  }

  const empIdNum = Number(employeeId);
  if (isNaN(empIdNum)) {
    res.status(400).json({ error: "employeeId must be a valid number" });
    return;
  }

  try {
    // Check if employee already has a reservation for this date
    const existing = getReservationByEmployeeAndDate(empIdNum, date);
    if (existing) {
      res.status(400).json({ error: "Employee already has a reservation for this date" });
      return;
    }

    // Check if spots are full
    const currentReservations = getReservationsByDate(date);
    if (currentReservations.length >= TOTAL_SPOTS) {
      res.status(400).json({ error: "No parking spots available for this date" });
      return;
    }

    // Find the first available spot number (1-indexed)
    const reservedSpotNumbers = new Set(currentReservations.map((r: Reservation) => r.spotNumber));
    let assignedSpot = -1;
    for (let i = 1; i <= TOTAL_SPOTS; i++) {
      if (!reservedSpotNumbers.has(i)) {
        assignedSpot = i;
        break;
      }
    }

    if (assignedSpot === -1) {
      res.status(400).json({ error: "No parking spots available for this date" });
      return;
    }

    insertReservation(empIdNum, date, assignedSpot);

    res.status(201).json({
      message: "Reservation successful",
      reservation: {
        employeeId: empIdNum,
        date,
        spotNumber: assignedSpot
      }
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message || "Internal server error" });
  }
});
